import { createHmac, timingSafeEqual } from "node:crypto";
import type { NextFunction, Request, Response } from "express";

export type AuthUser = {
  sub: string;
  email?: string;
  role?: string;
  app_metadata?: { role?: string };
  user_metadata?: { role?: string };
};

declare global {
  namespace Express {
    interface Request {
      user?: AuthUser;
    }
  }
}

function decodePart<T>(part: string): T | null {
  try {
    return JSON.parse(Buffer.from(part, "base64url").toString("utf8")) as T;
  } catch {
    return null;
  }
}

function verifyToken(token: string, secret: string): AuthUser | null {
  const [encodedHeader, encodedPayload, encodedSignature] = token.split(".");
  if (!encodedHeader || !encodedPayload || !encodedSignature) return null;

  const header = decodePart<{ alg?: string; typ?: string }>(encodedHeader);
  const payload = decodePart<AuthUser & { exp?: number }>(encodedPayload);
  if (header?.alg !== "HS256" || !payload?.sub) return null;
  if (payload.exp !== undefined && payload.exp <= Math.floor(Date.now() / 1000)) {
    return null;
  }

  const expected = createHmac("sha256", secret)
    .update(`${encodedHeader}.${encodedPayload}`)
    .digest();
  const provided = Buffer.from(encodedSignature, "base64url");
  return provided.length === expected.length &&
    timingSafeEqual(provided, expected)
    ? payload
    : null;
}

export function requireAuth(req: Request, res: Response, next: NextFunction) {
  const secret = process.env.SUPABASE_JWT_SECRET;
  if (!secret) {
    res.status(503).json({ error: "Authentication is not configured" });
    return;
  }

  const authorization = req.header("authorization");
  const token = authorization?.startsWith("Bearer ")
    ? authorization.slice("Bearer ".length).trim()
    : "";
  const user = token ? verifyToken(token, secret) : null;
  if (!user) {
    res.status(401).json({ error: "A valid bearer token is required" });
    return;
  }

  req.user = user;
  next();
}

export function requireAdmin(req: Request, res: Response, next: NextFunction) {
  requireAuth(req, res, () => {
    const role =
      req.user?.role ??
      req.user?.app_metadata?.role ??
      req.user?.user_metadata?.role;
    if (role !== "admin") {
      res.status(403).json({ error: "Administrator access required" });
      return;
    }
    next();
  });
}

import { Router } from "express";
import { eq } from "drizzle-orm";
import { db, profilesTable, scenariosTable } from "@workspace/db";
import { requireAuth } from "../middlewares/auth";

const router = Router();

router.get("/modes", async (_req, res) => {
  const modes = await db
    .select()
    .from(scenariosTable)
    .where(eq(scenariosTable.isActive, true));
  res.json(modes.filter((mode) => mode.isGlobal).map((mode) => ({
    ...mode,
    scenarioData: mode.scenarioData ?? {},
  })));
});

router.get("/profile", requireAuth, async (req, res) => {
  const profile = await db
    .select()
    .from(profilesTable)
    .where(eq(profilesTable.id, req.user!.sub))
    .limit(1);
  if (!profile[0]) {
    res.status(404).json({ error: "Profile not found" });
    return;
  }
  res.json(profile[0]);
});

export default router;

import { Router } from "express";
import { eq } from "drizzle-orm";
import {
  appSettingsTable,
  db,
  profilesTable,
  scenariosTable,
  subscriptionsTable,
  usersTable,
} from "@workspace/db";
import { requireAdmin } from "../middlewares/auth";

const router = Router();
router.use("/admin", requireAdmin);

router.get("/admin/users", async (_req, res) => {
  res.json(await db.select().from(profilesTable));
});

router.get("/admin/scenarios", async (_req, res) => {
  res.json(await db.select().from(scenariosTable));
});

router.post("/admin/scenarios", async (req, res) => {
  const { adminId, name, description, scenarioData, isGlobal = true } = req.body;
  if (typeof adminId !== "string" || typeof name !== "string" || !scenarioData) {
    res.status(400).json({ error: "adminId, name, and scenarioData are required" });
    return;
  }
  const created = await db.insert(scenariosTable).values({
    adminId,
    name: name.trim(),
    description: description ?? null,
    scenarioData,
    isGlobal: Boolean(isGlobal),
  }).returning();
  res.status(201).json(created[0]);
});

router.patch("/admin/scenarios/:id", async (req, res) => {
  const updated = await db.update(scenariosTable).set({
    ...(typeof req.body.name === "string" ? { name: req.body.name.trim() } : {}),
    ...(req.body.description !== undefined ? { description: req.body.description } : {}),
    ...(req.body.scenarioData !== undefined ? { scenarioData: req.body.scenarioData } : {}),
    ...(req.body.isActive !== undefined ? { isActive: Boolean(req.body.isActive) } : {}),
    updatedAt: new Date(),
  }).where(eq(scenariosTable.id, req.params.id)).returning();
  if (!updated[0]) {
    res.status(404).json({ error: "Scenario not found" });
    return;
  }
  res.json(updated[0]);
});

router.delete("/admin/scenarios/:id", async (req, res) => {
  const deleted = await db.delete(scenariosTable)
    .where(eq(scenariosTable.id, req.params.id))
    .returning({ id: scenariosTable.id });
  if (!deleted[0]) {
    res.status(404).json({ error: "Scenario not found" });
    return;
  }
  res.status(204).end();
});

router.get("/admin/settings", async (_req, res) => {
  const settings = await db.select().from(appSettingsTable).limit(1);
  res.json(settings[0] ?? {
    id: 1,
    interstitialIntervalMinutes: 2,
    rewardAdsForOneDay: 20,
    trialDays: 3,
  });
});

router.patch("/admin/settings", async (req, res) => {
  const { interstitialIntervalMinutes, rewardAdsForOneDay, trialDays } = req.body;
  if (![interstitialIntervalMinutes, rewardAdsForOneDay, trialDays]
    .every((value) => Number.isInteger(value))) {
    res.status(400).json({ error: "All settings must be integers" });
    return;
  }
  const updated = await db.insert(appSettingsTable).values({
    id: 1,
    interstitialIntervalMinutes,
    rewardAdsForOneDay,
    trialDays,
  }).onConflictDoUpdate({
    target: appSettingsTable.id,
    set: { interstitialIntervalMinutes, rewardAdsForOneDay, trialDays, updatedAt: new Date() },
  }).returning();
  res.json(updated[0]);
});

router.post("/admin/users/:userId/subscription", async (req, res) => {
  const { durationDays, note } = req.body;
  if (!Number.isInteger(durationDays) || durationDays < 1 || durationDays > 3650) {
    res.status(400).json({ error: "durationDays must be between 1 and 3650" });
    return;
  }
  const expiresAt = new Date(Date.now() + durationDays * 86400000);
  const updated = await db.update(usersTable).set({
    subscriptionStatus: "active",
    subscriptionExpiresAt: expiresAt,
    updatedAt: new Date(),
  }).where(eq(usersTable.id, req.params.userId)).returning();
  if (!updated[0]) {
    res.status(404).json({ error: "User not found" });
    return;
  }
  const subscription = await db.insert(subscriptionsTable).values({
    userId: req.params.userId,
    grantedBy: req.user!.sub,
    durationDays,
    expiresAt,
    note: typeof note === "string" ? note : null,
  }).returning();
  res.status(201).json(subscription[0]);
});

router.post("/admin/users/:userId/ban", async (req, res) => {
  const { banned = true, reason } = req.body;
  if (req.params.userId === req.user!.sub) {
    res.status(400).json({ error: "Administrators cannot ban themselves" });
    return;
  }
  const updated = await db.update(profilesTable).set({
    isBanned: Boolean(banned),
    banReason: banned && typeof reason === "string" ? reason.trim() || null : null,
    updatedAt: new Date(),
  }).where(eq(profilesTable.id, req.params.userId)).returning();
  if (!updated[0]) {
    res.status(404).json({ error: "Profile not found" });
    return;
  }
  res.json(updated[0]);
});

router.post("/admin/users/:userId/ad-free", async (req, res) => {
  const updated = await db.update(profilesTable).set({
    isAdFree: Boolean(req.body.adFree),
    updatedAt: new Date(),
  }).where(eq(profilesTable.id, req.params.userId)).returning();
  if (!updated[0]) {
    res.status(404).json({ error: "Profile not found" });
    return;
  }
  res.json(updated[0]);
});

export default router;

import { Router, type Response } from "express";

const router = Router();

function supabaseConfig() {
  const baseUrl = process.env.SUPABASE_URL;
  const publishableKey = process.env.SUPABASE_PUBLISHABLE_KEY;
  if (!baseUrl || !publishableKey) {
    throw new Error("Supabase authentication is not configured");
  }
  return { baseUrl: baseUrl.replace(/\/$/, ""), publishableKey };
}

async function forwardAuth(
  path: string,
  body: unknown,
  res: Response,
) {
  try {
    const { baseUrl, publishableKey } = supabaseConfig();
    const response = await fetch(`${baseUrl}/auth/v1/${path}`, {
      method: "POST",
      headers: {
        apikey: publishableKey,
        Authorization: `Bearer ${publishableKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });
    const text = await response.text();
    res.status(response.status).type("application/json").send(text);
  } catch (error) {
    res.status(503).json({
      error: error instanceof Error ? error.message : "Authentication unavailable",
    });
  }
}

router.post("/auth/signup", (req, res) =>
  forwardAuth("signup", req.body, res),
);
router.post("/auth/signin", (req, res) =>
  forwardAuth("token?grant_type=password", req.body, res),
);

export default router;

